from moler.exceptions import CommandFailure


class SynchronizeEnb(object):
    """Class for synchronizing eNBs."""

    def __init__(self, executor):
        self.executor = executor
        self.config = self.executor.config
        self.mapped_sectors = self.executor.mapped_sectors
        self.align_rtg_cell_to_small_cell = self.executor.align_rtg_cell_to_small_cell

    def synchronize_small_cell_link(self, enbs=[], attempts=3):
        """
        This keyword is used for synchronization link between rtg and enb

        :param enbs: list of enb devices --> each should be class of ta_moler.device.fzm_console.FzmConsole
        :param attempts: number of attempts, default 3
        :return: boolean
        """
        status = False

        self._enable_digital_domain_for_all_small_cell_enbs(enbs=enbs)
        for attempt in range(attempts):
            self._disable_and_enable_rx_sync_for_all_small_cell_enbs(enbs=enbs)
            try:
                self._synchronize_small_cell_link()
                status = True
                break
            except CommandFailure:
                continue

        return status

    def _enable_digital_domain_for_all_small_cell_enbs(self, enbs=[]):
        """
        Enabling digital domain for all small cell enbs
        :param enbs: list of enb devices --> each should be class of ta_moler.device.fzm_console.FzmConsole
        :return: None
        """
        for enb in enbs:
            if self._is_small_cell_enb(enb.number):
                cells_connected_via_obsai = self._get_obsai_cells(enb_number=enb.number)
                enb.enable_digital_domain(cells_connected_via_obsai)

    def _disable_and_enable_rx_sync_for_all_small_cell_enbs(self, enbs=[]):
        """
        Disable and enable rx sync for all small cell enbs
        :param enbs: list of enb devices --> each should be class of ta_moler.device.fzm_console.FzmConsole
        :return: None
        """
        for enb in enbs:
            if self._is_small_cell_enb(enb.number):
                cells_connected_via_obsai = self._get_obsai_cells(enb_number=enb.number)
                enb.disable_and_enable_rx_sync(cells_connected_via_obsai)

    def _is_small_cell_enb(self, enb_number):
        """
        Check if small cell enb - FZP/FZM
        :param enb_number:
        :return: True or False
        """
        enb_type = self.config['enb'][enb_number]['enb_type']
        if enb_type.upper() == 'FLEXI-FZM':
            return True
        return False

    def _get_obsai_cells(self, enb_number):
        """
        Get all cell connected via obsai with RTG
        :param enb_number:
        :return: list of obsai cells
        """
        obsai_cells = []
        for sector in self.mapped_sectors:
            if self.mapped_sectors[sector]['enb'] == int(enb_number) and \
                    self.mapped_sectors[sector]['connection'] == 'obsai':
                obsai_cells.append(self.mapped_sectors[sector]['cell'])
        return obsai_cells

    def _synchronize_small_cell_link(self):
        """
        Perform proper command to synchronize connection between enb and RTG
        :return: None
        """
        at_least_one_cell_is_connected_via_obsai = self.is_connected_via('obsai')
        at_least_one_cell_is_connected_via_cpri = self.is_connected_via('cpri')
        at_least_one_cell_is_connected_via_rf = self.is_connected_via('rf')

        if at_least_one_cell_is_connected_via_obsai:
            self.align_rtg_cell_to_small_cell()
        if at_least_one_cell_is_connected_via_cpri:
            self.align_rtg_cell_to_lbr_device()
        if at_least_one_cell_is_connected_via_rf:
            self.config_remote_fzmrfconfig()

    def is_connected_via(self, connection_type):
        """
        Check if at least one sector is connected via specified type.
        :param connection_type: Type of connection to check
        :return: True or False
        """
        for sector_number in self.mapped_sectors:
            if self.mapped_sectors[sector_number]['connection'] == connection_type:
                return True
        return False
